/* miniz_export.h — minimal shim for the vendored miniz (normally generated by
 * miniz's CMake export machinery; we build miniz as plain sources, so the export
 * macro is a no-op visibility attribute). */
#ifndef MINIZ_EXPORT_H
#define MINIZ_EXPORT_H
#ifndef MINIZ_EXPORT
#define MINIZ_EXPORT
#endif
#ifndef MINIZ_NO_EXPORT
#define MINIZ_NO_EXPORT
#endif
#ifndef MINIZ_DEPRECATED
#define MINIZ_DEPRECATED
#endif
#endif /* MINIZ_EXPORT_H */
